update action_step_instance
set status = #{status},
    attempt_count = #{attemptCount},
    payload_json = #{payloadJson},
    last_error_code = #{lastErrorCode},
    last_error_message = #{lastErrorMessage},
    version = version + 1,
    updated_at = #{updatedAt}
where id = #{id}
  and version = #{version}
